.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
b<-read.csv('outputs/stage6_foxp2_gnomad_narrow_variants.csv');d<-read.csv('outputs/stage6_foxp2_fi_cohort_region_aligned.csv');idx<-match(d$rs,b$rs);stopifnot(!anyNA(idx),!anyDuplicated(idx));N<-nrow(b);n<-nrow(d);R0<-matrix(readBin('work/stage6_foxp2_gnomad_nfe_narrow_ld.bin','double',n=N*N,size=8,endian='little'),N,N);R<-R0[idx,idx];dimnames(R)<-list(d$rs,d$rs);stopifnot(min(eigen(R,symmetric=TRUE,only.values=TRUE)$values)> -1e-8)
fits<-list();diags<-list();mem<-list();for(trait in c('UKB_FI','TwinGene_FI')){z<-if(trait=='UKB_FI')d$ukb_z else d$tg_z_adapter;Nsample<-if(trait=='UKB_FI')164610 else 10616;names(z)<-d$rs;l<-estimate_s_rss(z,R,n=Nsample);set.seed(42);f<-susie_rss(z=z,R=R,n=Nsample,L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[trait]]<-f;diags[[length(diags)+1]]<-data.frame(trait=trait,n=Nsample,n_variants=n,lambda=l,converged=f$converged,n_sets=length(f$sets$cs),max_pip=max(f$pip));if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){i<-f$sets$cs[[k]];mem[[length(mem)+1]]<-data.frame(trait=trait,component=f$sets$cs_index[k],rs=d$rs[i],pip=f$pip[i])};cat(trait,'lambda',l,'sets',length(f$sets$cs),'converged',f$converged,'\n');flush.console()};write.csv(do.call(rbind,diags),'outputs/stage6_foxp2_fi_cohort_susie_diagnostics.csv',row.names=FALSE);if(length(mem))write.csv(do.call(rbind,mem),'outputs/stage6_foxp2_fi_cohort_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_foxp2_fi_cohort_susie_fits.rds');a<-fits[['UKB_FI']];t<-fits[['TwinGene_FI']];if(a$converged&&t$converged&&length(a$sets$cs)&&length(t$sets$cs)){out<-list();for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(a,t,p1=1e-4,p2=1e-4,p12=p12)$summary);x$p12<-p12;out[[length(out)+1]]<-x};write.csv(do.call(rbind,out),'outputs/stage6_foxp2_fi_cohort_susie_coloc.csv',row.names=FALSE)}
